/// Returns true iff `n` is prime under the definition:
/// n >= 2 and for all k with 2 <= k < n, n % k != 0.
///
/// This implementation checks candidate divisors in increasing order
/// and returns false immediately upon finding any divisor.
///
/// Notes on safety/overflow:
/// - All computations are done in i16 to avoid i8 overflow for (n - d)
///   and to keep the termination measure well-defined.
pub fn is_prime(n: i8) -> bool {
    if n < 2 {
        return false;
    }

    let n16: i16 = n as i16;

    // Loop invariants (informal, aligned with the problem statement):
    // 1) n16 >= 2
    // 2) d is within [2, n16]
    // 3) For all j with 2 <= j < d, n16 % j != 0
    //
    // Termination measure (well-founded over non-negative integers):
    // measure = n16 - d, strictly decreases each iteration because d += 1.
    let mut d: i16 = 2;
    while d < n16 {
        if n16 % d == 0 {
            return false;
        }
        d += 1;
    }

    true
}